SELECT 
FROM regulatory_authority


        AND authority_code LIKE CONCAT('%', #{params.authorityCode}, '%')


        AND authority_name LIKE CONCAT('%', #{params.authorityName}, '%')


        AND authority_type = #{params.authorityType}


        AND country_code = #{params.countryCode}


        AND is_active = #{params.isActive}


        AND org_id = #{params.orgId}


ORDER BY create_time DESC

SELECT 
FROM regulatory_authority
WHERE authority_type = #{authorityType}
AND org_id = #{orgId}
AND is_active = 1
ORDER BY authority_name

SELECT COUNT(1)
FROM regulatory_authority
WHERE authority_code = #{authorityCode}
AND org_id = #{orgId}

    AND authority_id != #{authorityId}

SELECT COUNT(1)
FROM regulatory_report_template
WHERE authority_id = #{authorityId}

mapper.insert:
INSERT INTO regulatory_authority_backup (
    authority_id, authority_code, authority_name, authority_name_eng, authority_type,
    country_code, jurisdiction, contact_person, contact_phone, contact_email,
    address, website, is_active, remark, org_id, backup_note, backup_time, backup_by
)
SELECT authority_id, authority_code, authority_name, authority_name_eng, authority_type,
       country_code, jurisdiction, contact_person, contact_phone, contact_email,
       address, website, is_active, remark, org_id, #{backupNote}, NOW(), #{backupBy}
FROM regulatory_authority
WHERE authority_id = #{authorityId}

INSERT INTO regulatory_authority_log (
    authority_id, operation_type, operation_desc, operation_by, operation_time
) VALUES (
    #{authorityId}, #{operationType}, #{operationDesc}, #{operationBy}, NOW()
)

mapper.select:
SELECT authority_type, COUNT(*) as total_count, SUM(CASE WHEN is_active = 1 THEN 1 ELSE 0 END) as active_count, SUM(CASE WHEN is_active = 0 THEN 1 ELSE 0 END) as inactive_count FROM regulatory_authority
AND org_id = #{params.orgId}
AND create_time >= #{params.startDate}
AND create_time <= #{params.endDate}
GROUP BY authority_type ORDER BY total_count DESC

SELECT a.authority_id, a.authority_name, a.authority_type, COUNT(DISTINCT t.template_id) as template_count, COUNT(DISTINCT r.report_id) as report_count, AVG(CASE WHEN r.report_status = 'ACCEPTED' THEN 1 ELSE 0 END) as success_rate FROM regulatory_authority a LEFT JOIN regulatory_report_template t ON a.authority_id = t.authority_id LEFT JOIN regulatory_report r ON t.template_id = r.template_id
AND a.org_id = #{params.orgId}
AND a.authority_type = #{params.authorityType}
GROUP BY a.authority_id, a.authority_name, a.authority_type ORDER BY report_count DESC

SELECT 'authority_code' as field_name, '机构编码重复' as error_message, authority_code as field_value FROM regulatory_authority WHERE authority_code IN
#{item.authorityCode}
AND org_id = #{orgId}

SELECT authority_code as "机构编码", authority_name as "机构名称", authority_name_eng as "英文名称", authority_type as "机构类型", country_code as "国家代码", jurisdiction as "管辖范围", contact_person as "联系人", contact_phone as "联系电话", contact_email as "联系邮箱", address as "地址", website as "网站", CASE WHEN is_active = 1 THEN '启用' ELSE '停用' END as "状态", remark as "备注", create_time as "创建时间" FROM regulatory_authority
AND authority_type = #{params.authorityType}
AND is_active = #{params.isActive}
AND org_id = #{params.orgId}
ORDER BY create_time DESC

SELECT
    operation_type,
    operation_desc,
    operation_by,
    operation_time
FROM regulatory_authority_log
WHERE authority_id = #{authorityId}

    AND operation_time >= #{params.startDate}


    AND operation_time <= #{params.endDate}

ORDER BY operation_time DESC

mapper.delete:
DELETE FROM regulatory_authority_backup
WHERE backup_time < DATE_SUB(NOW(), INTERVAL #{retentionDays} DAY)
AND org_id = #{orgId}

mapper.select:
SELECT
    DATE(create_time) as date,
    COUNT(*) as new_authorities,
    SUM(CASE WHEN is_active = 1 THEN 1 ELSE 0 END) as active_authorities
FROM regulatory_authority


        AND org_id = #{params.orgId}


        AND create_time >= #{params.startDate}


        AND create_time <= #{params.endDate}


GROUP BY DATE(create_time)
ORDER BY date DESC

SELECT '监管机构总数' as metric_name, COUNT(*) as metric_value, 'count' as metric_type FROM regulatory_authority WHERE org_id = #{params.orgId}
UNION ALL
SELECT '活跃机构数' as metric_name, COUNT(*) as metric_value, 'count' as metric_type FROM regulatory_authority WHERE org_id = #{params.orgId} AND is_active = 1
UNION ALL
SELECT '机构类型数' as metric_name, COUNT(DISTINCT authority_type) as metric_value, 'count' as metric_type FROM regulatory_authority WHERE org_id = #{params.orgId}
